// File ini di-generate otomatis dari dokumen sumber materi kelas 8.
// Jangan diubah manual: sunting dokumen sumber lalu jalankan ulang
// tools/generate_materi_dart.ps1 agar format tetap konsisten.

import '../models/materi_content.dart';

/// Materi PPKn SMP Kelas 8.
const List<MateriSection> materiKelas8 = <MateriSection>[
  MateriSection(
    id: 'kelas8-materi-1',
    number: 1,
    title: 'Kedudukan Pancasila Dalam Kehidupan Berbangsa Dan Bernegara',
    summary: 'Pancasila bukan sekadar teks yang kita bacakan setiap upacara bendera hari Senin. Lebih dari itu, Pancasila adalah jiwa, napas, dan pedoman utama bagi kita semua, termasuk bagi kalian yang saat ini sedang duduk di bangku Sekolah Menengah Pertama (SMP). Di usia remaja ini, kalian mulai mengenal dunia yang lebih luas, bergaul dengan banyak teman dengan latar belakang berbeda, dan menghadapi berbagai tantangan baru. Di sinilah Pancasila hadir sebagai "sahabat" yang memandu langkah kalian. Mari kita bedah bagaimana sebenarnya peran Pancasila dalam kehidupan sehari-hari melalui tiga sudut pandang utama: sebagai Dasar Negara, Pandangan Hidup Bangsa, dan Ideologi Negara.',
    blocks: <MateriBlock>[
      MateriBlock(MateriBlockType.bullet, 'Pemahaman Pancasila sebagai Dasar Negara'),
      MateriBlock(MateriBlockType.paragraph, 'Pernahkah kamu membayangkan bagaimana sebuah negara yang sangat besar, dengan jutaan penduduk dan ribuan pulau, bisa berdiri kokoh dan tidak hancur berantakan? Jawabannya ada pada sebuah konsep penting yang kita sebut sebagai "Dasar Negara". Bagi bangsa Indonesia, dasar negara kita adalah Pancasila. Mungkin selama ini kamu sering mendengar kata Pancasila, membacanya setiap hari Senin saat upacara bendera, atau melihat lambang burung Garuda di dinding kelas. Namun, pernahkah kamu benar-benar memikirkan apa sebenarnya maksud dari "Pancasila sebagai dasar negara"? Mengapa sebuah negara harus memiliki dasar? Mari kita lupakan sejenak bahasa buku pelajaran yang rumit. Kita akan membahasnya dengan cara yang sangat sederhana dan dekat dengan kehidupan kita sehari-hari, agar kamu bisa melihat betapa keren dan pentingnya fungsi Pancasila bagi negara kita tercinta ini.'),
      MateriBlock(MateriBlockType.bullet, 'Analogi Fondasi Sebuah Gedung Pencakar Langit'),
      MateriBlock(MateriBlockType.paragraph, 'Bayangkan kamu sedang melihat sebuah gedung pencakar langit yang sangat tinggi. Gedung itu memiliki desain yang megah, kaca yang berkilau, lift yang sangat cepat, dan ratusan ruangan di dalamnya. Gedung itu adalah perumpamaan dari Negara Kesatuan Republik Indonesia. Kita punya banyak pulau yang indah, sumber daya alam yang melimpah, dan rakyat yang hebat. Akan tetapi, sehebat apapun desain gedung tersebut, ia tidak akan bisa berdiri tegak tanpa satu hal yang paling krusial: Fondasi yang tertanam kuat di dalam tanah. Fondasi ini mungkin tidak selalu terlihat dari luar. Orang-orang sibuk mengagumi kaca dan tingginya gedung, tanpa mempedulikan beton baja di bawah tanah. Tapi, ketika terjadi badai besar, angin kencang, atau gempa bumi, fondasi inilah yang menahan gedung tersebut agar tidak ambruk dan hancur lebur.'),
      MateriBlock(MateriBlockType.paragraph, 'Dalam konteks negara kita, Pancasila adalah fondasi baja tersebut. Sebagai dasar negara, Pancasila adalah tempat berpijaknya seluruh bangunan pemerintahan dan kehidupan bernegara di Indonesia. Ketika dunia berubah dengan sangat cepat, ketika ada masalah ekonomi global, atau ketika ada perbedaan pendapat yang tajam di antara masyarakat, Pancasila-lah yang menahan negara ini agar tidak runtuh. Tanpa dasar yang kuat, negara kita akan mudah goyah dan terpecah belah oleh berbagai masalah.'),
      MateriBlock(MateriBlockType.bullet, 'Pancasila Sebagai "Sumber dari Segala Sumber Hukum'),
      MateriBlock(MateriBlockType.paragraph, 'Selain sebagai fondasi bangunan, Pancasila sebagai dasar negara juga berfungsi layaknya sebuah "Buku Aturan Main Utama". Coba bayangkan kamu sedang bermain sebuah game online multiplayer atau bermain sepak bola bersama teman-temanmu. Apa yang terjadi jika tidak ada aturan sama sekali? Pemain sepak bola mungkin akan menggunakan tangan mereka untuk memasukkan bola, atau pemain game akan menggunakan cheat sesuka hati. Pasti permainannya akan kacau, tidak adil, dan berujung pada pertengkaran, bukan? Negara juga begitu. Agar ratusan juta orang bisa hidup berdampingan dengan damai, kita butuh aturan yang mengikat semua orang, yang disebut dengan hukum atau undang-undang. Nah, di Indonesia, kita punya banyak sekali aturan. Ada aturan tentang lalu lintas (agar kita tidak tabrakan di jalan), aturan tentang penggunaan internet (agar kita tidak menyebarkan berita bohong), aturan tentang pendidikan, aturan tentang jual beli, dan masih banyak lagi.'),
      MateriBlock(MateriBlockType.paragraph, 'Lalu, dari mana semua aturan itu dibuat? Apakah pemerintah boleh membuat aturan sembarangan? Jawabannya adalah tidak. Semua aturan dan hukum yang dibuat di Indonesia harus bersumber dan tidak boleh bertentangan dengan Pancasila. Inilah makna sejati dari dasar negara. Pancasila adalah bosnya semua hukum. Jika pemerintah atau Dewan Perwakilan Rakyat (DPR) membuat sebuah undang-undang baru, aturan tersebut harus diuji terlebih dahulu: apakah aturan ini sesuai dengan prinsip-prinsip dasar Pancasila? Jika ada sebuah aturan yang ternyata merugikan masyarakat, membeda-bedakan orang berdasarkan latar belakangnya, atau tidak adil, maka aturan tersebut dianggap melanggar dasar negara dan harus dibatalkan. Jadi, Pancasila berfungsi sebagai saringan pelindung, memastikan semua hukum di Indonesia dibuat untuk kebaikan, keadilan, dan kesejahteraan seluruh rakyat tanpa terkecuali.'),
      MateriBlock(MateriBlockType.bullet, 'Pancasila Sebagai "Kompas" Penyelenggaraan Negara'),
      MateriBlock(MateriBlockType.paragraph, 'Sekarang, mari kita ubah analoginya. Bayangkan Negara Indonesia adalah sebuah kapal laut yang raksasa. Di dalam kapal ini ada lebih dari 270 juta penumpang. Kapal ini sedang berlayar mengarungi samudra yang luas untuk menuju sebuah tujuan, yaitu masa depan yang sejahtera, adil, dan makmur. Di dalam kapal tersebut, tentu ada kapten dan awak kapal. Merekalah yang kita sebut sebagai pemerintah (Presiden, Menteri, Gubernur, Bupati, hingga Wali Kota). Tugas mereka adalah mengemudikan kapal negara ini. Tapi, samudra itu luas dan seringkali dipenuhi kabut tebal atau badai. Bagaimana kapten kapal tahu arah yang benar agar tidak tersesat atau menabrak karang?'),
      MateriBlock(MateriBlockType.paragraph, 'Mereka membutuhkan kompas. Sebagai dasar negara, Pancasila berfungsi sebagai kompas petunjuk arah bagi pemerintah dalam menjalankan tugasnya. Setiap kali pemerintah ingin membuat program kerja, membangun jalan tol, merancang kurikulum pendidikan untuk anak SMP seperti kamu, atau merencanakan anggaran negara, mereka harus melihat ke arah yang ditunjuk oleh "kompas" Pancasila. Pemerintah tidak boleh menjalankan negara hanya untuk mementingkan kelompoknya sendiri atau memperkaya diri sendiri. Mereka harus selalu ingat bahwa tujuan menjalankan negara ini adalah untuk menciptakan keadilan sosial, merawat kemanusiaan, dan menjaga persatuan. Kompas Pancasila memastikan bahwa siapapun yang menjadi presidennya, siapapun yang menjadi menterinya, arah kapal Indonesia tetap sama dan tidak melenceng dari tujuan awalnya.'),
      MateriBlock(MateriBlockType.bullet, 'Pancasila Sebagai "Lem Perekat" Keberagaman'),
      MateriBlock(MateriBlockType.paragraph, 'Fungsi Pancasila sebagai dasar negara juga sangat penting dalam perannya sebagai "lem" yang merekatkan kita semua. Kamu pasti tahu bahwa Indonesia itu sangat unik. Sangat jarang ada negara di dunia ini yang memiliki perbedaan sebanyak Indonesia. Kita punya ribuan suku yang berbeda, ratusan bahasa daerah yang tidak sama antara satu pulau dan pulau lainnya, serta berbagai macam agama dan kepercayaan. Secara logika, negara dengan perbedaan yang sangat ekstrem seperti ini sangat mudah untuk pecah dan terbagi menjadi puluhan negara kecil yang berbeda-beda. Namun, kenyataannya, dari Sabang di ujung barat pulau Sumatra, hingga Merauke di ujung timur pulau Papua, kita semua tetap bangga menyebut diri kita sebagai orang Indonesia.'),
      MateriBlock(MateriBlockType.paragraph, 'Mengapa bisa begitu? Karena kita berpijak pada dasar yang sama. Pancasila memberikan kita titik temu. Dasar negara kita ini dirancang sedemikian rupa agar bisa diterima oleh semua golongan, baik yang mayoritas maupun yang minoritas. Tidak ada satu suku pun yang lebih diistimewakan dari suku lain di atas dasar negara kita. Tidak ada kelompok yang boleh menindas kelompok lain. Dasar negara kita menjamin bahwa semua orang memiliki tempat yang sama, hak yang sama, dan kewajiban yang sama di rumah besar bernama Indonesia.'),
      MateriBlock(MateriBlockType.paragraph, 'Setelah membaca uraian di atas, kamu sekarang sudah menyadari bahwa Pancasila sebagai dasar negara bukanlah sekadar teks panjang yang harus kamu hafalkan saat pelajaran Pendidikan Pancasila dan Kewarganegaraan (PPKn). Pancasila juga bukan sekadar kalimat yang dibacakan oleh pembina upacara dan diikuti oleh seluruh siswa setiap hari Senin. Pancasila adalah fondasi tempat kamu berdiri dengan aman di negara ini. Ia adalah sumber dari segala aturan yang melindungi hak-hakmu sebagai warga negara. Ia adalah kompas yang memastikan pemimpin negara bekerja untuk kepentinganmu. Dan ia adalah lem yang membuat kamu bisa berteman dengan siapa saja dari seluruh penjuru Nusantara tanpa harus bermusuhan karena perbedaan. Sebagai siswa SMP yang merupakan generasi penerus bangsa, memahami Pancasila sebagai dasar negara adalah langkah awal yang sangat hebat. Karena suatu saat nanti, kapal raksasa bernama Indonesia ini akan diserahkan kemudinya kepada generasi kalian. Jika kalian sudah paham bahwa negara ini memiliki dasar, fondasi, dan kompas yang bernama Pancasila, maka kalian tidak akan pernah kehilangan arah dalam membawa Indonesia menuju masa depan yang jauh lebih luar biasa!'),
      MateriBlock(MateriBlockType.bullet, 'Pancasila sebagai Pandangan Hidup Bangsa'),
      MateriBlock(MateriBlockType.paragraph, 'Supaya kamu lebih mudah membedakannya, ingatlah rumus sederhana ini: Jika Dasar Negara itu berbicara tentang bagaimana pemerintah dan negara diurus, maka Pandangan Hidup itu berbicara tentang bagaimana kamu, aku, dan kita semua (rakyatnya) bersikap, berpikir, dan bertingkah laku dalam kehidupan sehari-hari.'),
      MateriBlock(MateriBlockType.paragraph, 'Mari kita bedah konsep "Pandangan Hidup Bangsa" ini menggunakan perumpamaan-perumpamaan yang seru dan dekat dengan dunia anak SMP!'),
      MateriBlock(MateriBlockType.bullet, 'Analogi Kacamata untuk Melihat Dunia'),
      MateriBlock(MateriBlockType.paragraph, 'Bayangkan kamu dan temanmu sedang memakai kacamata dengan lensa warna yang berbeda. Kamu memakai kacamata berlensa kuning, sedangkan temanmu memakai kacamata berlensa biru. Ketika kalian melihat sebuah tembok putih, kamu akan bilang tembok itu kuning, sedangkan temanmu akan ngotot bahwa tembok itu biru. Cara kita melihat dunia sangat bergantung pada "kacamata" apa yang kita pakai.'),
      MateriBlock(MateriBlockType.paragraph, 'Dalam kehidupan berbangsa, Pancasila adalah kacamata yang dipakai oleh seluruh rakyat Indonesia. Kacamata Pancasila ini membentuk cara kita memandang masalah, merespons kejadian, dan memperlakukan orang lain. Misalnya, ketika ada tetangga atau teman yang sedang tertimpa musibah. Jika seseorang memakai "kacamata individualisme" (mementingkan diri sendiri), dia mungkin akan berpikir, "Ah, itu kan masalah dia, bukan urusanku." Tetapi, karena orang Indonesia memakai "kacamata Pancasila", yang kita lihat adalah, "Dia saudaraku sebangsa, aku harus membantunya." Itulah mengapa tradisi gotong royong sangat kuat di negara kita. Kacamata Pancasila membuat kita melihat dunia dengan lensa kemanusiaan, kebersamaan, dan rasa peduli.'),
      MateriBlock(MateriBlockType.bullet, 'Pancasila Sebagai "DNA" atau Kepribadian Unik Kita'),
      MateriBlock(MateriBlockType.paragraph, 'Setiap orang di kelasmu pasti punya kepribadian yang berbeda, kan? Ada yang pendiam tapi pintar, ada yang ceria dan suka melawak, ada yang tegas dan berjiwa pemimpin. Kepribadian itulah yang membuat mereka unik dan mudah dikenali. "Oh, kalau yang suka senyum dan ramah itu pasti si Budi!" Sama seperti manusia, sebuah negara dan bangsa juga punya kepribadian atau "DNA". Pancasila sebagai pandangan hidup adalah DNA asli bangsa Indonesia. Sejak zaman dahulu, jauh sebelum negara Indonesia merdeka, nenek moyang kita sudah memiliki kebiasaan-kebiasaan yang luar biasa. Mereka selalu percaya pada Tuhan, bersikap ramah, suka berkumpul untuk musyawarah jika ada masalah, dan selalu bekerja sama membangun desa. Kebiasaan-kebiasaan baik yang sudah mendarah daging inilah yang kemudian dirumuskan dan diberi nama "Pancasila".'),
      MateriBlock(MateriBlockType.paragraph, 'Jadi, Pancasila itu bukan sesuatu yang tiba-tiba diimpor dari luar negeri lalu dipaksakan kepada kita. Pancasila adalah cerminan wajah kita sendiri. Ketika kamu bersikap sopan kepada guru, menghargai teman yang berbeda agama saat mereka sedang beribadah, atau menyelesaikan masalah ekstrakurikuler dengan cara berdiskusi (bukan berantem), kamu sebenarnya sedang menunjukkan DNA asli Indonesia. Kamu sedang menghidupkan Pancasila.'),
      MateriBlock(MateriBlockType.bullet, '"Buku Panduan Bergaul" di Masyarakat'),
      MateriBlock(MateriBlockType.paragraph, 'Kalau kamu baru pertama kali merakit mainan Lego atau memainkan sebuah video game baru, hal pertama yang pasti kamu butuhkan adalah Manual Book atau buku panduan, bukan? Buku panduan itu memberi tahu kamu apa yang boleh dilakukan, apa yang tidak boleh, dan bagaimana cara agar mainanmu bisa terbentuk dengan sempurna. Sebagai pandangan hidup, Pancasila berfungsi layaknya Buku Panduan Bergaul bagi masyarakat Indonesia. Sebagai anak SMP, keseharianmu dipenuhi dengan interaksi. Kamu bergaul dengan teman di kelas, bermain dengan teman di kompleks rumah, hingga berinteraksi dengan orang tak dikenal di media sosial. Terkadang, interaksi ini bisa memicu konflik. Misalnya, ada teman yang suka mengejek, atau ada yang memaksakan kehendak saat kerja kelompok.'),
      MateriBlock(MateriBlockType.paragraph, 'Di sinilah buku panduan itu bekerja. Pancasila memberikan petunjuk bagaimana kita harus bersikap agar hidup berdampingan terasa nyaman. Panduan ini mengajarkan kita untuk tidak melakukan bullying (karena melanggar nilai kemanusiaan), mengajarkan kita untuk tidak membeda-bedakan teman yang kaya atau miskin (nilai keadilan), dan mengajarkan kita untuk mengutamakan kekompakan kelas di atas ego pribadi (nilai persatuan). Dengan mengikuti panduan ini, kehidupan bermasyarakat kita akan aman, damai, dan chill.'),
      MateriBlock(MateriBlockType.bullet, 'Pancasila Sebagai "Filter" di Era Digital'),
      MateriBlock(MateriBlockType.paragraph, 'Saat ini, kita hidup di era globalisasi dan internet. Hanya dengan membuka TikTok, Instagram, atau YouTube, kamu bisa melihat gaya hidup orang dari Amerika, Eropa, Korea, hingga Jepang. Semua informasi, budaya, dan kebiasaan dari seluruh dunia masuk ke HP-mu setiap detiknya. Apakah itu hal yang buruk? Tentu saja tidak! Kita butuh belajar teknologi dari luar, kita boleh menikmati musik K-Pop, atau menonton film-film keren dari Hollywood. Namun, kita ibarat sedang meminum air dari sungai yang sangat deras. Jika kita langsung menelannya tanpa disaring, kuman dan kotorannya bisa ikut tertelan dan membuat kita sakit. Di sinilah Pancasila bertugas sebagai filter atau saringan.'),
      MateriBlock(MateriBlockType.paragraph, 'Sebagai pandangan hidup, Pancasila membantu kita menyaring mana budaya asing yang baik dan mana yang buruk.'),
      MateriBlock(MateriBlockType.bullet, 'Contoh yang lolos filter: Budaya disiplin waktu dari Jepang, atau etos kerja keras dan kemajuan teknologi dari negara Barat. Itu sangat bagus dan sesuai dengan semangat kita untuk maju!'),
      MateriBlock(MateriBlockType.bullet, 'Contoh yang tidak lolos filter: Gaya hidup terlalu bebas yang tidak menghormati orang tua, sikap apatis (cuek) terhadap lingkungan sekitar, atau kebiasaan berkata-kata kasar di internet. Itu harus kita saring dan buang, karena tidak sesuai dengan "DNA" kesopanan dan kemanusiaan bangsa kita.'),
      MateriBlock(MateriBlockType.paragraph, 'Dengan punya filter yang kuat, kita bisa menjadi anak muda yang gaul, modern, dan berwawasan global, tanpa harus kehilangan identitas kita sebagai orang Indonesia yang beradab.'),
      MateriBlock(MateriBlockType.paragraph, 'Sekarang kamu sudah bisa melihat bedanya, kan? Jika dasar negara adalah pijakan hukum dan aturan bagi pemerintah untuk menjalankan negara, maka Pancasila sebagai pandangan hidup adalah pedoman tingkah laku bagi kita semua. Pancasila tidak hanya hidup di dalam gedung MPR/DPR atau di Istana Negara. Pancasila justru hidup dan bernapas di dalam ruang kelasmu, di kantin sekolah saat kamu mengantre dengan tertib, di lapangan basket saat kamu bermain sportif, dan di kolom komentar media sosial saat kamu mengetikkan kata-kata yang positif. Sebagai anak SMP, kamu tidak perlu menunggu menjadi menteri atau presiden untuk menerapkan Pancasila. Cukup dengan menjadi teman yang asyik, pelajar yang jujur, dan anak yang menghormati orang tua, kamu sudah membuktikan bahwa Pancasila benar-benar menjadi pandangan hidupmu. Bagaimana menurutmu, dari perumpamaan kacamata, DNA, buku panduan, atau filter di era digital, mana yang paling menggambarkan tantangan anak muda seusiamu saat ini dalam menerapkan Pancasila sehari-hari?'),
      MateriBlock(MateriBlockType.bullet, 'Pancasila sebagai Ideologi Negara'),
      MateriBlock(MateriBlockType.paragraph, 'Kita sudah membahas Pancasila sebagai Dasar Negara (fondasi dan aturan bagi negara) dan Pancasila sebagai Pandangan Hidup (pedoman tingkah laku kita sehari-hari). Nah, sekarang kita sampai pada level yang paling puncak dan sering dianggap paling rumit: Pancasila sebagai Ideologi Negara.'),
      MateriBlock(MateriBlockType.paragraph, 'Kata "ideologi" memang terdengar berat, seperti bahasa profesor di televisi. Padahal, kalau kita bedah, kata ini berasal dari kata idea yang berarti gagasan, konsep, atau cita-cita. Jadi, secara sederhana, ideologi adalah kumpulan ide atau cita-cita besar yang ingin dicapai oleh suatu bangsa. Jika dasar negara adalah "fondasinya", dan pandangan hidup adalah "kacamata sehari-harinya", maka ideologi adalah "Mimpi Besar" dan "Misi Utama" kita di masa depan. Supaya lebih seru, mari kita bedah konsep "Ideologi Negara" ini dengan bahasa dan analogi yang dekat dengan keseharianmu!'),
      MateriBlock(MateriBlockType.bullet, 'Analogi Blueprint (Cetak Biru) dalam Game Membangun Kota'),
      MateriBlock(MateriBlockType.paragraph, 'Pernahkah kamu bermain game membangun kota seperti Minecraft, SimCity, atau Cities: Skylines? Sebelum kamu menaruh blok pertama atau membangun jalan raya, kamu pasti sudah punya bayangan di kepalamu: "Aku ingin membangun kota yang canggih, banyak tamannya, warganya bahagia, dan tidak macet." Bayangan atau rancangan awal itulah yang disebut dengan blueprint (cetak biru). Dalam konteks negara kita, Pancasila sebagai ideologi adalah blueprint masa depan Indonesia. Para pendiri bangsa kita dulu duduk bersama dan membayangkan, "Mau jadi seperti apa negara Indonesia ini di masa depan?"'),
      MateriBlock(MateriBlockType.paragraph, 'Mereka tidak ingin Indonesia menjadi negara yang hanya kaya raya tapi rakyatnya saling bermusuhan. Mereka juga tidak ingin Indonesia menjadi negara yang teknologinya maju tapi melupakan Tuhan. Maka, mereka membuat blueprint bernama Pancasila: Sebuah negara impian yang masyarakatnya religius, memanusiakan manusia, bersatu padu, mengutamakan musyawarah, dan memiliki keadilan sosial bagi seluruh rakyatnya. Ideologi inilah rancangan masa depan yang sedang kita bangun sama-sama hari ini.'),
      MateriBlock(MateriBlockType.bullet, 'Main Quest (Misi Utama) yang Menggerakkan Bangsa'),
      MateriBlock(MateriBlockType.paragraph, 'Kalau kamu suka bermain game RPG (Role-Playing Game), kamu pasti tahu bedanya side quest (misi sampingan) dan main quest (misi utama). Kamu bisa melakukan banyak misi sampingan seperti memancing, mengumpulkan koin, atau membantu warga desa, tapi tujuan akhirmu tetap satu: mengalahkan bos terakhir untuk menamatkan game tersebut. Sebagai ideologi, Pancasila adalah Main Quest bangsa Indonesia.'),
      MateriBlock(MateriBlockType.paragraph, 'Negara kita punya banyak sekali kegiatan atau "misi sampingan". Pemerintah sibuk membangun jalan tol, bapak/ibu guru sibuk mengajar di sekolah, dokter sibuk mengobati pasien di rumah sakit, dan kamu sibuk belajar untuk ujian. Apa tujuan dari semua kesibukan itu? Kenapa kita semua harus repot-repot bekerja keras? Jawabannya ada pada ideologi kita. Semua energi, keringat, dan pikiran rakyat Indonesia dikerahkan untuk menyelesaikan main quest kita, yaitu mencapai keadilan sosial dan kesejahteraan bagi seluruh rakyat. Ideologi inilah yang memberi kita motivasi dan alasan mengapa kita harus terus maju sebagai sebuah bangsa. Ia adalah energi yang menggerakkan 270 juta orang menuju garis finish yang sama.'),
      MateriBlock(MateriBlockType.bullet, 'Antivirus dan Firewall Pelindung Sistem Negara'),
      MateriBlock(MateriBlockType.paragraph, 'Di dunia nyata, Indonesia tidak sendirian. Kita hidup berdampingan dengan banyak negara lain yang memiliki "mimpi besar" atau ideologi yang berbeda-beda. Ada negara penganut ideologi Liberalisme yang sangat membebaskan warganya hingga terkadang kebablasan dan sangat mementingkan diri sendiri (individualis). Ada juga yang menganut ideologi Komunisme di mana semuanya diatur sangat ketat oleh negara sampai warga tidak punya kebebasan pribadi. Di era internet saat ini, paham-paham atau ide-ide dari luar itu bisa dengan sangat mudah masuk ke otak kita melalui media sosial. Terkadang, ide-ide asing tersebut berbahaya dan bisa merusak persatuan kita.'),
      MateriBlock(MateriBlockType.paragraph, 'Di sinilah Pancasila berfungsi sebagai Antivirus atau Firewall pelindung. Sama seperti laptop atau smartphone kamu yang butuh antivirus agar sistemnya tidak rusak terkena malware, negara kita juga butuh antivirus ideologi. Ketika ada ideologi asing masuk yang mengajarkan kebencian, radikalisme, atau memecah belah agama (virus), sistem ideologi Pancasila di dalam otak kita akan langsung mendeteksinya dan memblokirnya: "Tunggu dulu, ajaran ini bertentangan dengan kemanusiaan dan persatuan Indonesia. Ini virus, harus kita delete!" Ideologi Pancasila menjaga negara kita agar tidak mudah terbawa arus atau dijajah secara pikiran oleh bangsa lain, karena kita sudah punya sistem pertahanan dan prinsip kita sendiri yang sangat kuat.'),
      MateriBlock(MateriBlockType.bullet, 'Chant (Yel-Yel) Suporter yang Menyatukan Semangat'),
      MateriBlock(MateriBlockType.paragraph, 'Bayangkan kamu sedang berada di stadion sepak bola yang sangat besar, menonton Timnas Indonesia bertanding. Di sana ada puluhan ribu orang dari berbagai daerah, berbeda suku, berbeda pekerjaan, dan tidak saling kenal. Tapi, ketika dirigen suporter mulai menyanyikan chant atau yel-yel dukungan, tiba-tiba puluhan ribu orang itu bernyanyi bersama dengan suara yang menggelegar dan kompak. Bulu kudukmu pasti merinding melihat kekompakan itu.'),
      MateriBlock(MateriBlockType.paragraph, 'Pancasila sebagai ideologi berfungsi persis seperti Yel-Yel penyemangat bangsa. Dalam perjalanan menuju masa depan, bangsa kita pasti sering mengalami masa-masa sulit. Mungkin ada krisis ekonomi, bencana alam besar, atau masa-masa sulit seperti pandemi beberapa waktu lalu. Di saat negara sedang terpuruk dan warga mulai panik, ideologi inilah yang diteriakkan kembali untuk menyatukan semangat kita. Nilai-nilai ideologi mengingatkan kita bahwa kita adalah satu tim. Saat ada daerah yang terkena bencana gempa, daerah lain tanpa disuruh langsung mengirimkan bantuan dan relawan. Semangat kebersamaan yang tiba-tiba bangkit secara otomatis ini adalah bukti nyata bahwa "yel-yel" ideologi Pancasila bekerja dengan sangat baik di dalam jiwa masyarakat Indonesia.'),
      MateriBlock(MateriBlockType.paragraph, 'Selamat! Sekarang kamu sudah memiliki pemahaman lengkap tentang tiga fungsi utama Pancasila. Jika kita gabungkan ketiganya, ini adalah ringkasan super singkatnya:'),
      MateriBlock(MateriBlockType.bullet, 'Dasar Negara: Aturan main dan fondasi hukum (Bagi Pemerintah).'),
      MateriBlock(MateriBlockType.bullet, 'Pandangan Hidup: Pedoman sikap dan tingkah laku sehari-hari (Bagi Kamu/Masyarakat).'),
      MateriBlock(MateriBlockType.bullet, 'Ideologi Negara: Cita-cita masa depan, pelindung dari pengaruh buruk, dan penggerak semangat bangsa (Bagi Masa Depan Indonesia).'),
      MateriBlock(MateriBlockType.paragraph, 'Memahami Pancasila sebagai ideologi menyadarkan kita bahwa bangsa ini tidak hanya berjalan mengalir mengikuti arus tanpa arah. Kita punya tujuan yang jelas, mimpi yang besar, dan pelindung yang kuat. Dan kamu, sebagai generasi muda yang nantinya akan memegang kendali negara ini, adalah tokoh utama yang akan menyelesaikan blueprint dan menamatkan main quest bangsa ini.'),
      MateriBlock(MateriBlockType.paragraph, 'Dari ketiga analogi keren di atas (Pancasila sebagai Blueprint, Main Quest, atau Antivirus), mana nih yang menurutmu paling mudah dipahami untuk dijelaskan kepada teman-teman sebangkumu besok di sekolah?'),
    ],
  ),
  MateriSection(
    id: 'kelas8-materi-2',
    number: 2,
    title: 'UUD Negara Republik Indonesia Tahun 1945',
    summary: 'Bayangkan sebuah permainan sepak bola tanpa aturan yang jelas, tanpa wasit, dan tanpa garis batas lapangan. Pasti permainannya akan sangat kacau, bukan? Nah, sebuah negara juga memiliki prinsip yang sama. Agar negara bisa berdiri tegak, berjalan teratur, dan melindungi seluruh rakyatnya, negara membutuhkan "aturan main" yang sangat kuat. Bagi negara kita tercinta, Indonesia, aturan main tertinggi itu adalah Undang-Undang Dasar Negara Republik Indonesia (UUD NRI) Tahun 1945.',
    blocks: <MateriBlock>[
      MateriBlock(MateriBlockType.paragraph, 'Suasana Sidang Perumusan UUD 1945.'),
      MateriBlock(MateriBlockType.paragraph, 'Source: Kompaspedia - Kompas.id'),
      MateriBlock(MateriBlockType.paragraph, 'Sebagai pelajar SMP yang merupakan generasi penerus bangsa, memahami UUD 1945 bukan sekadar tugas menghafal teks saat upacara bendera di hari Senin. Lebih dari itu, ini adalah tentang memahami bagaimana fondasi rumah besar bernama "Indonesia" ini dibangun dan bagaimana kita semua harus merawatnya. Mari kita pelajari bersama tiga poin utama mengenai pedoman berharga negara kita ini.'),
      MateriBlock(MateriBlockType.bullet, 'Memahami Proses Perumusan dan Pengesahan UUD NRI Tahun 1945'),
      MateriBlock(MateriBlockType.paragraph, 'Proses lahirnya UUD 1945 tidaklah instan apalagi mudah. Ada keringat, perdebatan pemikiran yang panjang, dan semangat luar biasa dari para pendiri bangsa (founding fathers) kita. Proses pembentukannya bahkan sudah dimulai sebelum kemerdekaan diproklamasikan.'),
      MateriBlock(MateriBlockType.bullet, 'Masa Perumusan oleh BPUPKI'),
      MateriBlock(MateriBlockType.paragraph, 'Dalam rangka mempersiapkan negara yang merdeka, dibentuklah Badan Penyelidik Usaha-usaha Persiapan Kemerdekaan Indonesia (BPUPKI). Badan ini mengadakan dua kali sidang resmi yang menjadi tonggak sejarah konstitusi kita:'),
      MateriBlock(MateriBlockType.bullet, 'Sidang Pertama (29 Mei – 1 Juni 1945): Sidang ini berfokus pada perumusan dasar negara. Para tokoh saling bertukar gagasan, hingga akhirnya lahirlah rumusan Pancasila sebagai landasan filosofis bangsa yang nantinya menjiwai seluruh isi UUD 1945.'),
      MateriBlock(MateriBlockType.bullet, 'Sidang Kedua (10 – 17 Juli 1945): Pada sidang ini, fokus bergeser pada penyusunan bentuk wilayah, bentuk negara, dan perumusan undang-undang dasar. BPUPKI membentuk "Panitia Hukum Dasar" yang diketuai oleh Ir. Soekarno. Untuk mempercepat kerja, dibentuklah "Panitia Perancang Undang-Undang Dasar" di bawah pimpinan Prof. Mr. Dr. Soepomo. Mereka memeras otak menyusun pasal demi pasal. Setelah diskusi dan revisi yang matang, naskah rancangan UUD akhirnya diterima secara bulat pada tanggal 16 Juli 1945.'),
      MateriBlock(MateriBlockType.bullet, 'Masa Pengesahan oleh PPKI'),
      MateriBlock(MateriBlockType.paragraph, 'Tanggal 17 Agustus 1945, bangsa kita membacakan proklamasi kemerdekaan. Sehari setelahnya, sebuah negara baru tentu tidak bisa dibiarkan kosong tanpa struktur pemerintahan yang sah. Maka, pada tanggal 18 Agustus 1945, Panitia Persiapan Kemerdekaan Indonesia (PPKI) segera menggelar sidang yang menghasilkan tiga keputusan penting:'),
      MateriBlock(MateriBlockType.bullet, 'Mengesahkan UUD 1945 sebagai konstitusi negara Republik Indonesia.'),
      MateriBlock(MateriBlockType.bullet, 'Menetapkan Ir. Soekarno sebagai Presiden dan Drs. Mohammad Hatta sebagai Wakil Presiden.'),
      MateriBlock(MateriBlockType.bullet, 'Membentuk Komite Nasional Indonesia Pusat (KNIP) untuk membantu tugas Presiden sementara MPR dan DPR belum terbentuk.'),
      MateriBlock(MateriBlockType.paragraph, 'Sejak ketukan palu sidang PPKI pada tanggal 18 Agustus itulah, UUD 1945 resmi menjadi hukum pedoman jalannya pemerintahan bangsa kita. Jejak perumusan konstitusi ini meninggalkan banyak warisan fisik maupun nilai kebiasaan yang masih bertahan hingga saat ini. Berikut beberapa potret sejarah dan penerapannya yang patut kamu kenali:'),
      MateriBlock(MateriBlockType.paragraph, 'Gedung Pancasila Jakarta.'),
      MateriBlock(MateriBlockType.paragraph, 'Source: Republika.id / Kisah Rumah Panglima Belanda jadi Tempat Lahir Pancasila'),
      MateriBlock(MateriBlockType.paragraph, 'Naskah Asli UUD 1945.'),
      MateriBlock(MateriBlockType.paragraph, 'Source: Wikipedia / Undang-Undang Dasar Negara Republik Indonesia Tahun 1945'),
      MateriBlock(MateriBlockType.bullet, 'Fungsi dan Kedudukan UUD NRI Tahun 1945'),
      MateriBlock(MateriBlockType.paragraph, 'Setelah disahkan, di mana sebenarnya posisi UUD 1945 dalam kehidupan bernegara kita, dan apa peran utamanya? Di Indonesia, kita hidup berdampingan dengan banyak aturan, mulai dari Undang-Undang (UU), Peraturan Presiden, Peraturan Pemerintah, hingga Peraturan Daerah (Perda). Dalam piramida peraturan hukum di Indonesia, UUD NRI Tahun 1945 menempati kedudukan paling tinggi.'),
      MateriBlock(MateriBlockType.paragraph, 'UUD 1945 berstatus sebagai hukum dasar tertulis. Ini bermakna bahwa setiap aturan perundang-undangan lain yang ada di Indonesia bersumber padanya dan sama sekali tidak boleh bertentangan dengan isi UUD 1945. Jika suatu saat ada aturan daerah atau undang-undang yang menyimpang dari nilai UUD 1945, maka aturan tersebut harus dievaluasi dan dibatalkan demi hukum.'),
      MateriBlock(MateriBlockType.paragraph, 'Secara lebih detail, pedoman negara kita ini memegang tiga fungsi utama bagi pemerintahan dan warga negara:'),
      MateriBlock(MateriBlockType.bullet, 'Sebagai Alat Kontrol: UUD 1945 berfungsi sebagai tolak ukur dan alat pemeriksa (check and balance). Ia mengontrol aturan hukum yang lebih rendah agar selalu berpedoman pada nilai-nilai keadilan dan konstitusi yang lebih tinggi.'),
      MateriBlock(MateriBlockType.bullet, 'Sebagai Pengatur: UUD 1945 menentukan desain bangunan negara. Aturan ini membagi dan mengatur kekuasaan agar tidak terjadi penumpukan kekuasaan pada satu pihak. UUD menetapkan mana tugas Presiden (Pemerintah/Eksekutif), mana wewenang pembuat hukum (DPR/Legislatif), dan ranah pengadilan (Yudikatif).'),
      MateriBlock(MateriBlockType.bullet, 'Sebagai Penentu: UUD 1945 berfungsi sebagai penegas hak-hak dan kewajiban kita. Dari dokumen inilah ditentukan bahwa seluruh anak bangsa berhak mendapat pendidikan yang layak, dijamin kebebasannya untuk beragama, sekaligus memiliki kewajiban untuk patuh pada hukum serta membela negara saat diperlukan.'),
      MateriBlock(MateriBlockType.bullet, 'Berani Menjalankan UUD NRI Tahun 1945 di Lingkungan Tempat Tinggal'),
      MateriBlock(MateriBlockType.paragraph, 'Seringkali pelajar merasa bahwa urusan Undang-Undang Dasar adalah urusan orang dewasa, pejabat, atau para politikus di Senayan. Padahal, ruh UUD 1945 itu sejatinya hidup dalam tindakan sehari-hari warga negaranya. Menjalankan nilai-nilai UUD tidak harus menunggu kamu dewasa; kamu harus berani memulainya sekarang dari lingkungan sekitar tempat tinggalmu. Apa yang dimaksud dengan "berani menjalankan"? Artinya, kamu tidak sekadar hafal teori dari buku sekolah, tetapi bersedia mengambil tindakan nyata sekalipun itu berarti kamu harus lebih peduli, turun tangan, dan menyisihkan sedikit waktu bermainmu. Berikut contoh-contoh tindakan pelajar berani:'),
      MateriBlock(MateriBlockType.bullet, 'Berani Menghargai Keberagaman Agama (Praktik Pasal 29 UUD 1945)'),
      MateriBlock(MateriBlockType.paragraph, 'Di kompleks perumahan atau desamu, kemungkinan besar terdapat tetangga yang memeluk keyakinan berbeda. Menjalankan UUD berarti kamu berani bersikap toleran dalam tindakan. Tidak berbuat bising saat mereka sedang mengadakan ibadah di rumahnya, mengucapkan selamat pada hari rayanya, dan bergaul bebas dengan teman sekitar tanpa pernah membedakan agama atau suku.'),
      MateriBlock(MateriBlockType.bullet, 'Menghidupkan Gotong Royong (Nilai Demokrasi Sosial UUD)'),
      MateriBlock(MateriBlockType.paragraph, 'Daripada terus-menerus bermain gawai, pelajar yang berani mempraktikkan UUD akan dengan senang hati mengambil bagian saat warga sekitar mengadakan kerja bakti akhir pekan. Membantu menyapu jalan, membersihkan balai warga, atau setidaknya ikut menjaga kebersihan fasilitas umum di sekitarmu adalah wujud tanggung jawab sosial yang diamanatkan oleh pendiri bangsa.'),
      MateriBlock(MateriBlockType.bullet, 'Berani Menuntut dan Menjalankan Hak Pendidikan (Praktik Pasal 31 UUD 1945)'),
      MateriBlock(MateriBlockType.paragraph, 'Negara menjamin pendidikan dasar bagimu. Membalas jaminan tersebut berarti kamu harus berani melawan kemalasan. Belajar dengan gigih, tidak mudah menyerah di saat menemui pelajaran yang sulit, dan menjauhkan diri dari ajakan hal-hal negatif seperti membolos. Lebih mulia lagi jika kamu berani berbagi ilmu kepada teman atau adik-adik tetangga di lingkunganmu yang kesulitan belajar.'),
      MateriBlock(MateriBlockType.bullet, 'Menjaga Keamanan Lingkungan Bersama (Bela Negara dalam Pasal 30 UUD 1945)'),
      MateriBlock(MateriBlockType.paragraph, 'Wujud bela negara bagi seorang remaja bukanlah mengangkat senjata di medan perang, melainkan menjaga ketertiban lingkungan terdekat. Kamu bisa memulainya dengan mematuhi jam malam sehingga tidak begadang sambil membuat keributan di pos ronda, menjaga kelestarian taman warga, atau berani melapor kepada Ketua RT/RW jika melihat kejadian yang membahayakan lingkungan.'),
      MateriBlock(MateriBlockType.bullet, 'Berani Melawan Ketidakadilan Sosial'),
      MateriBlock(MateriBlockType.paragraph, 'Jika kamu melihat ada anak di lingkunganmu yang dikucilkan atau bahkan di-bully secara tidak wajar, mempraktikkan UUD berarti kamu tidak boleh diam saja. Konstitusi menjamin setiap warganya bebas dari perlakuan merendahkan. Bantulah melerai atau laporkan segera masalah tersebut kepada orang dewasa yang bisa memberikan jalan keluar terbaik.'),
      MateriBlock(MateriBlockType.paragraph, 'UUD NRI Tahun 1945 sama sekali bukan pajangan atau buku tebal usang yang hanya layak dibaca di dalam kelas. Konstitusi ini adalah kompas hidup masyarakat yang sangat dinamis. Melalui pemahaman yang mendalam mengenai sejarah kelahirannya yang sulit, mengetahui fungsi krusialnya sebagai hukum tertinggi, serta keberanianmu untuk mempraktikkan nilainya di lingkungan tempat tinggal, kamu sedang mengambil porsi dalam mempertahankan negara.'),
      MateriBlock(MateriBlockType.paragraph, 'Kamu bukanlah sekadar anak remaja biasa, kamu adalah warga negara terdidik yang bertugas merawat tiang-tiang bangunan Republik Indonesia. Mulailah berlatih dari hal sekecil apa pun di rumahmu sendiri hari ini!'),
    ],
  ),
  MateriSection(
    id: 'kelas8-materi-3',
    number: 3,
    title: 'Peraturan Perundang-Undangan',
    summary: 'Setiap lingkungan, mulai dari skala terkecil di dalam rumah hingga skala terbesar sebuah negara, membutuhkan aturan untuk menjaga ketertiban, keadilan, dan keamanan. Tanpa aturan, kehidupan bersama akan menjadi kacau karena setiap orang akan bertindak hanya berdasarkan keinginan dan kepentingan pribadinya. Sebagai warga negara sekaligus pelajar, memahami bagaimana aturan ini dibuat, disusun, dan diterapkan adalah langkah pertama untuk menjadi pribadi yang bertanggung jawab.',
    blocks: <MateriBlock>[
      MateriBlock(MateriBlockType.bullet, 'Peraturan di Rumahku, Sekolahku, Lingkunganku, dan Negaraku'),
      MateriBlock(MateriBlockType.paragraph, 'Aturan tidak hanya milik polisi atau pemerintah; aturan hidup berdampingan dengan kita setiap hari dan ruang lingkupnya terus membesar seiring dengan ke mana kita melangkah.'),
      MateriBlock(MateriBlockType.bullet, 'Peraturan di Rumah: Ini adalah fondasi pertama kedisiplinan. Aturan di rumah dibuat oleh orang tua atau kesepakatan keluarga untuk menjaga keharmonisan. Contohnya adalah batasan jam menonton televisi, aturan merapikan tempat tidur sendiri, atau kewajiban berpamitan sebelum keluar rumah.'),
      MateriBlock(MateriBlockType.bullet, 'Peraturan di Sekolah: Saat kamu melangkah ke SMP, kamu terikat oleh tata tertib sekolah. Aturan ini dibuat agar proses belajar mengajar berjalan lancar dan karakter siswa terbentuk. Contohnya adalah kewajiban memakai seragam sesuai hari, datang tepat waktu sebelum bel berbunyi, larangan melakukan perundungan (bullying), dan kewajiban mengerjakan tugas.'),
      MateriBlock(MateriBlockType.bullet, 'Peraturan di Lingkungan Masyarakat: Di lingkungan RT/RW atau desa, aturan dibuat berdasarkan kesepakatan warga agar kehidupan bertetangga aman dan damai. Bentuknya bisa berupa kewajiban lapor bagi tamu yang menginap lebih dari 1x24 jam, jadwal ronda malam, atau aturan membuang sampah pada tempatnya.'),
      MateriBlock(MateriBlockType.bullet, 'Peraturan di Negara: Ini adalah aturan dengan cakupan paling luas yang mengikat seluruh rakyat Indonesia. Aturan ini dibuat oleh lembaga negara yang berwenang dan dilengkapi dengan sanksi tegas bagi pelanggarnya. Contohnya adalah kewajiban memiliki SIM bagi pengendara kendaraan bermotor, larangan mencuri, dan kewajiban membayar pajak.'),
      MateriBlock(MateriBlockType.bullet, 'Pengertian Tata Urutan Perundang-undangan'),
      MateriBlock(MateriBlockType.heading, 'Negara Indonesia memiliki ribuan peraturan, mulai dari undang-undang di tingkat nasional hingga peraturan daerah di tingkat kota. Agar tidak terjadi kebingungan atau benturan antara satu aturan dengan aturan lainnya, diperlukan sebuah sistem yang disebut Tata Urutan Perundang-undangan.'),
      MateriBlock(MateriBlockType.paragraph, 'Tata urutan ini dapat dibayangkan seperti sebuah piramida. Aturan yang berada di puncak piramida memiliki kedudukan tertinggi, dan aturan-aturan yang berada di bawahnya harus bersumber serta patuh pada aturan di atasnya. Dalam ilmu hukum, ada prinsip penting yang berbunyi: peraturan yang lebih rendah tidak boleh bertentangan dengan peraturan yang lebih tinggi. Jika sebuah aturan di tingkat daerah (misalnya Peraturan Wali Kota) bertentangan dengan Undang-Undang Dasar, maka aturan daerah tersebut tidak sah dan harus dibatalkan. Sistem tata urutan ini berfungsi untuk memberikan kepastian hukum. Warga negara tahu pasti aturan mana yang menjadi pedoman utama, dan para pembuat kebijakan (seperti DPR dan Presiden) memiliki rel yang jelas saat akan merumuskan aturan baru agar tetap sejalan dengan cita-cita negara.'),
      MateriBlock(MateriBlockType.bullet, 'Jenis dan Tata Urutan Peraturan Perundang-undangan'),
      MateriBlock(MateriBlockType.paragraph, 'Berdasarkan Undang-Undang Nomor 12 Tahun 2011 (yang telah diubah dengan UU No. 15 Tahun 2019 dan UU No. 13 Tahun 2022), jenis dan hierarki peraturan perundang-undangan di Indonesia diurutkan dari yang paling tinggi ke yang paling rendah sebagai berikut:'),
      MateriBlock(MateriBlockType.bullet, 'Undang-Undang Dasar Negara Republik Indonesia (UUD NRI) Tahun 1945: Hukum dasar tertulis tertinggi di Indonesia. UUD 1945 memuat prinsip-prinsip dasar negara, bentuk negara, dan hak asasi manusia.'),
      MateriBlock(MateriBlockType.bullet, 'Ketetapan Majelis Permusyawaratan Rakyat (Tap MPR): Keputusan yang dikeluarkan oleh MPR yang berisi hal-hal bersifat makro dan mengikat ke dalam maupun ke luar majelis.'),
      MateriBlock(MateriBlockType.bullet, 'Undang-Undang (UU)/Peraturan Pemerintah Pengganti Undang-Undang (Perppu): UU dibuat oleh Dewan Perwakilan Rakyat (DPR) bersama Presiden. Sedangkan Perppu ditetapkan oleh Presiden dalam kondisi yang sangat genting dan memaksa, namun harus mendapat persetujuan DPR di masa sidang berikutnya.'),
      MateriBlock(MateriBlockType.bullet, 'Peraturan Pemerintah (PP): Aturan yang dibuat oleh Presiden untuk menjalankan Undang-Undang sebagaimana mestinya. PP mengatur teknis pelaksanaan dari sebuah UU.'),
      MateriBlock(MateriBlockType.bullet, 'Peraturan Presiden (Perpres): Peraturan yang ditetapkan oleh Presiden untuk menjalankan perintah dari peraturan perundang-undangan yang lebih tinggi atau dalam menyelenggarakan kekuasaan pemerintahan.'),
      MateriBlock(MateriBlockType.bullet, 'Peraturan Daerah (Perda) Provinsi: Aturan yang dibuat oleh Dewan Perwakilan Rakyat Daerah (DPRD) Provinsi bersama dengan Gubernur. Aturan ini hanya berlaku di wilayah provinsi tersebut.'),
      MateriBlock(MateriBlockType.bullet, 'Peraturan Daerah (Perda) Kabupaten/Kota: Aturan tingkat daerah yang dibuat oleh DPRD Kabupaten/Kota bersama Bupati atau Wali Kota. Aturan ini sangat spesifik menyesuaikan dengan karakteristik, budaya, dan kebutuhan masyarakat di kabupaten atau kota tersebut.'),
      MateriBlock(MateriBlockType.bullet, 'Implementasi Peraturan Perundang-undangan'),
      MateriBlock(MateriBlockType.paragraph, 'Peraturan perundang-undangan tidak akan ada gunanya jika hanya menjadi teks di atas kertas. Implementasi berarti penerapan atau pelaksanaan aturan-aturan tersebut dalam kehidupan nyata. Sebuah Undang-Undang atau Peraturan Daerah dikatakan berhasil diimplementasikan jika tujuan dari aturan tersebut tercapai. Misalnya, Undang-Undang Lalu Lintas mewajibkan pengendara motor memakai helm berstandar SNI (Standar Nasional Indonesia). Implementasinya melibatkan dua pihak:'),
      MateriBlock(MateriBlockType.bullet, 'Pihak Aparat Penegak Hukum: Polisi lalu lintas melakukan patroli, memberikan tilang bagi pelanggar, dan memberikan edukasi di sekolah-sekolah tentang keselamatan berkendara.'),
      MateriBlock(MateriBlockType.bullet, 'Pihak Warga Negara: Masyarakat menyadari bahwa memakai helm bukan sekadar untuk menghindari polisi, melainkan untuk melindungi kepala dari cedera fatal saat terjadi kecelakaan, sehingga mereka memakainya secara sadar.'),
      MateriBlock(MateriBlockType.paragraph, 'Contoh lainnya di tingkat daerah adalah implementasi Perda tentang Kawasan Tanpa Rokok (KTR). Implementasi nyata di lapangan adalah terpasangnya rambu larangan merokok di rumah sakit, sekolah, atau angkutan umum, serta adanya petugas Satpol PP yang menindak warga yang nekat merokok di area tersebut.'),
      MateriBlock(MateriBlockType.bullet, 'Komitmen Penerapan Tata Urutan Peraturan Perundang-undangan di Indonesia'),
      MateriBlock(MateriBlockType.paragraph, 'Membangun negara yang teratur membutuhkan komitmen kuat dari penyelenggara negara (pemerintah) maupun seluruh warganya. Bagi seorang pelajar SMP, komitmen terhadap penerapan peraturan perundang-undangan diwujudkan melalui kesadaran hukum. Kesadaran hukum tidak datang tiba-tiba, melainkan dibentuk melalui empat tahapan utama:'),
      MateriBlock(MateriBlockType.bullet, 'Mengetahui Hukum (Pengetahuan): Kamu menyadari dan mengetahui bahwa ada aturan-aturan tertentu yang berlaku, seperti Undang-Undang Informasi dan Transaksi Elektronik (UU ITE) yang melarang penyebaran hoaks di media sosial.'),
      MateriBlock(MateriBlockType.bullet, 'Memahami Hukum (Pemahaman): Kamu mengerti mengapa aturan itu dibuat. Kamu paham bahwa dilarang menyebarkan hoaks karena hal itu bisa memicu kebencian, merugikan orang lain, dan memecah belah bangsa.'),
      MateriBlock(MateriBlockType.bullet, 'Menghargai Hukum (Sikap): Kamu membenarkan dan setuju bahwa aturan tersebut memang baik dan diperlukan. Kamu memiliki sikap batin yang menolak perbuatan melanggar hukum.'),
      MateriBlock(MateriBlockType.bullet, 'Berperilaku Hukum (Tindakan): Ini adalah puncak dari komitmen. Kamu secara nyata mematuhi aturan tersebut dalam tindakan sehari-hari, misalnya dengan selalu menyaring informasi sebelum membagikannya (share) di grup obrolan kelas, tidak melakukan cyberbullying, dan selalu mematuhi tata tertib sekolah meskipun tidak sedang diawasi oleh guru.'),
      MateriBlock(MateriBlockType.paragraph, 'Berkomitmen pada hukum berarti kamu memahami bahwa peraturan perundang-undangan diciptakan bukan untuk mengekang kebebasanmu, melainkan untuk melindungi kebebasanmu agar tidak diganggu oleh kebebasan orang lain yang tidak bertanggung jawab.'),
    ],
  ),
  MateriSection(
    id: 'kelas8-materi-4',
    number: 4,
    title: 'Melestarikan Budaya Bangsa',
    summary: 'Indonesia adalah negara kepulauan luar biasa yang membentang dari Sabang sampai Merauke, dihuni oleh ratusan suku bangsa dengan keanekaragaman tradisi, adat istiadat, tarian, lagu daerah, hingga kearifan lokal. Kekayaan warisan leluhur ini bukan sekadar peninggalan masa lalu yang disimpan di museum, melainkan pilar utama yang menyokong kehidupan berbangsa dan bernegara hari ini. Sebagai generasi muda di jenjang Sekolah Menengah Pertama (SMP), kalian memegang peranan kunci sebagai penerus dan penjaga warisan berharga ini agar tidak punah tertelan zaman.',
    blocks: <MateriBlock>[
      MateriBlock(MateriBlockType.bullet, 'Pelestarian Tradisi, Kearifan Lokal, dan Budaya Nasional'),
      MateriBlock(MateriBlockType.paragraph, 'Memahami upaya melestarikan kebudayaan, kita perlu membedakan dan memahami tiga tingkatan budaya yang ada di sekitar kita: tradisi, kearifan lokal, dan budaya nasional.'),
      MateriBlock(MateriBlockType.bullet, 'Tradisi'),
      MateriBlock(MateriBlockType.paragraph, 'Tradisi adalah kebiasaan atau tata cara yang diwariskan secara turun-temurun dari generasi ke generasi dalam suatu kelompok masyarakat tertentu. Tradisi mencakup berbagai aspek kehidupan, seperti upacara adat pernikahan, tradisi potong rambut gimbal di Dieng, tradisi lompat batu (Hombo Batu) di Nias, hingga tradisi Sekaten di Yogyakarta dan Surakarta. Tradisi mencerminkan bagaimana nenek moyang kita memaknai hubungan antara manusia, alam, dan Sang Pencipta.'),
      MateriBlock(MateriBlockType.bullet, 'Kearifan Lokal (Local Wisdom)'),
      MateriBlock(MateriBlockType.paragraph, 'Kearifan lokal adalah pandangan hidup, pengetahuan, dan gagasan bijak yang tumbuh dan berkembang di tengah masyarakat lokal untuk menyikapi lingkungan sekitar. Kearifan lokal sering kali berwujud aturan atau ajaran yang mengandung nilai kepedulian terhadap alam dan sesama. Contohnya:'),
      MateriBlock(MateriBlockType.bullet, 'Subak di Bali: Sistem irigasi pertanian tradisional yang berasaskan keadilan, kebersamaan, dan filosofi Tri Hita Karana (keharmonisan antara manusia, alam, dan Tuhan).'),
      MateriBlock(MateriBlockType.bullet, 'Hutan Larangan Adat: Kepercayaan atau aturan adat di berbagai daerah yang melarang masyarakat menebang pohon secara sembarangan di area hutan tertentu demi menjaga keseimbangan ekosistem dan pasokan air.'),
      MateriBlock(MateriBlockType.bullet, 'Sasi di Maluku dan Papua: Aturan adat untuk menunda pemanenan hasil laut atau darat dalam kurun waktu tertentu agar flora dan fauna memiliki kesempatan untuk berkembang biak.'),
      MateriBlock(MateriBlockType.bullet, 'Budaya Nasional'),
      MateriBlock(MateriBlockType.paragraph, 'Budaya nasional adalah puncak-puncak budaya daerah yang diakui secara luas oleh seluruh masyarakat Indonesia dan menjadi milik bersama seluruh bangsa. Budaya nasional lahir dari pembauran, penyaringan, dan pengangkatan budaya-budaya lokal yang memiliki nilai luhur dan dapat memperkuat rasa kebangsaan. Contoh budaya nasional antara lain batik, wayang kulit, tari reog, musik angklung, pencak silat, hingga bahasa Indonesia sebagai bahasa persatuan.'),
      MateriBlock(MateriBlockType.paragraph, 'Melestarikan budaya bukan berarti kita harus hidup secara kuno atau menolak kemajuan zaman. Pelestarian budaya dapat dilakukan melalui dua cara utama:'),
      MateriBlock(MateriBlockType.bullet, 'Culture Experience (Pelestarian melalui Pengalaman Langsung): Terjun langsung mempelajari, mempraktikkan, dan memainkan budaya tersebut. Contohnya, bergabung dalam ekstrakurikuler seni tari daerah di sekolah, belajar memainkan alat musik tradisional seperti angklung atau gamelan, serta memakai pakaian batik dalam kegiatan sehari-hari.'),
      MateriBlock(MateriBlockType.bullet, 'Culture Knowledge (Pelestarian melalui Pengetahuan): Mempelajari, mendokumentasikan, dan menyebarkan informasi tentang kebudayaan daerah. Di era digital saat ini, pelajar SMP bisa melestarikan budaya dengan cara membuat konten edukatif seperti video, artikel, atau kiriman media sosial mengenai keunikan tradisi di daerah masing-masing.'),
      MateriBlock(MateriBlockType.bullet, 'Budaya Nasional sebagai Alat Pemersatu Bangsa'),
      MateriBlock(MateriBlockType.paragraph, 'Indonesia memiliki lebih dari 1.300 suku bangsa dan lebih dari 700 bahasa daerah. Dengan keberagaman sejauh itu, apa yang membuat bangsa kita tetap bersatu dan tidak terpecah belah? Salah satu perekat utamanya adalah Budaya Nasional.'),
      MateriBlock(MateriBlockType.bullet, 'Jembatan Komunikasi dan Nilai Bersama'),
      MateriBlock(MateriBlockType.paragraph, 'Meskipun setiap suku memiliki budaya dan bahasa daerahnya sendiri, keberadaan budaya nasional menciptakan nilai-nilai bersama (shared values) yang dapat diterima oleh seluruh warga negara. Bahasa Indonesia, misalnya, merupakan produk budaya nasional yang sangat efektif menjembatani komunikasi antarwarga dari latar belakang suku yang berbeda. Tanpa bahasa nasional, seorang siswa dari Sumatra akan kesulitan berinteraksi dengan siswa dari Papua.'),
      MateriBlock(MateriBlockType.bullet, 'Penguat Semangat Gotong Royong dan Kebersamaan'),
      MateriBlock(MateriBlockType.paragraph, 'Banyak kebudayaan daerah di Indonesia yang mengandung nilai gotong royong dan musyawarah. Ketika nilai-nilai ini diangkat menjadi bagian dari budaya nasional, seluruh warga Indonesia merasa memiliki ikatan kekeluargaan yang kuat. Tradisi saling bantu saat musibah, kerja bakti membersihkan lingkungan, serta semangat toleransi beragama adalah cerminan dari budaya nasional yang menyatukan kita sebagai satu keluarga besar Indonesia.'),
      MateriBlock(MateriBlockType.bullet, 'Mencegah Konflik Antardaerah'),
      MateriBlock(MateriBlockType.paragraph, 'Ketika kita memandang kebudayaan daerah bukan sebagai milik satu kelompok saja, melainkan sebagai kekayaan bersama milik seluruh bangsa, rasa saling menghargai akan tumbuh. Seorang siswa Jawa yang menghargai keindahan Tari Pendet dari Bali, atau seorang siswa Sulawesi yang bangga akan keindahan Kain Ulos dari Sumatra Utara, secara tidak langsung sedang memperkuat ikatan persaudaraan nasional. Budaya nasional menghilangkan sekat-sekat kedaerahan dan mengubah perbedaan menjadi alasan untuk saling melengkapi.'),
      MateriBlock(MateriBlockType.bullet, 'Budaya Nasional sebagai Identitas dan Jati Diri Bangsa'),
      MateriBlock(MateriBlockType.paragraph, 'Di tengah arus globalisasi yang sangat pesat, budaya asing seperti musik pop luar negeri, tarian modern, hingga gaya busana barat dengan mudah masuk dan memengaruhi gaya hidup remaja. Di sinilah pentingnya memahami budaya nasional sebagai identitas dan jati diri bangsa.'),
      MateriBlock(MateriBlockType.bullet, 'Pengertian Identitas dan Jati Diri Bangsa'),
      MateriBlock(MateriBlockType.paragraph, 'Identitas bangsa adalah ciri khas atau tanda pengenal yang membedakan bangsa Indonesia dari bangsa-bangsa lain di dunia. Ketika orang luar melihat kain batik dengan motifnya yang rumit dan bermakna, mereka langsung mengenalnya sebagai produk khas Indonesia. Begitu pula ketika melihat kesenian pencak silat, masyarakat dunia tahu bahwa olahraga bela diri tersebut mengutamakan keindahan seni dan ketahanan mental khas Indonesia.'),
      MateriBlock(MateriBlockType.bullet, 'Membentengi Diri dari Dampak Negatif Globalisasi'),
      MateriBlock(MateriBlockType.paragraph, 'Globalisasi membawa banyak dampak positif seperti kemajuan teknologi dan akses informasi yang cepat. Namun, globalisasi juga membawa risiko pengikisan nilai-nilai lokal jika remaja kehilangan pegangan. Budaya nasional berfungsi sebagai filter (penyaring) kultural. Dengan memiliki pemahaman budaya yang kuat, pelajar SMP dapat memilah mana budaya luar yang bermanfaat (seperti disiplin kerja dan penguasaan teknologi) dan mana yang tidak sesuai dengan kepribadian bangsa (seperti sikap individualistis dan konsumeristik).'),
      MateriBlock(MateriBlockType.bullet, 'Kebanggaan di Kancah Internasional'),
      MateriBlock(MateriBlockType.paragraph, 'Budaya nasional yang lestari memberikan rasa bangga (national pride) ketika kita berhadapan dengan dunia luar. Banyak warisan budaya Indonesia yang telah diakui oleh lembaga dunia UNESCO sebagai Warisan Budaya Takbenda Dunia (Intangible Cultural Heritage), seperti Batik, Wayang, Keris, Angklung, Tari Saman, Pencak Silat, dan Gamelan. Pengakuan internasional ini membuktikan bahwa budaya nasional kita tidak hanya bernilai tinggi bagi bangsa sendiri, tetapi juga memberikan kontribusi berharga bagi peradaban dunia.'),
      MateriBlock(MateriBlockType.heading, 'Sebagai generasi muda, Pelajar SMP tidak perlu menunggu hingga menjadi pejabat atau tokoh masyarakat untuk mulai bergerak. Langkah-langkah kecil berikut dapat kalian lakukan mulai dari sekarang:'),
      MateriBlock(MateriBlockType.bullet, 'Bangga Menggunakan Produk dan Karya Budaya Lokal: Bangga mengenakan batik atau pakaian adat saat momen tertentu, serta mencintai kuliner tradisional Indonesia.'),
      MateriBlock(MateriBlockType.bullet, 'Aktif Mempelajari Seni Budaya di Sekolah: Mengikuti kegiatan seni tari, musik daerah, atau klub bahasa daerah dalam kegiatan ekstrakurikuler.'),
      MateriBlock(MateriBlockType.bullet, 'Memanfaatkan Media Sosial secara Positif: Mengunggah konten-konten menarik mengenai sejarah, keunikan tradisi, atau tempat wisata budaya di daerahmu agar makin dikenal luas oleh teman sebayamu.'),
      MateriBlock(MateriBlockType.bullet, 'Menerapkan Sikap Ramah dan Santun: Menunjukkan keramahtamahan, toleransi, dan rasa hormat yang menjadi ciri khas kepribadian bangsa Indonesia dalam kehidupan sehari-hari.'),
      MateriBlock(MateriBlockType.paragraph, 'Dengan terus menjaga, mempelajari, dan mencintai kebudayaan sendiri, kalian memastikan bahwa identitas bangsa Indonesia akan tetap tegak berdiri kokoh dan bercahaya, tidak hanya hari ini, tetapi juga untuk masa-masa yang akan datang.'),
    ],
  ),
  MateriSection(
    id: 'kelas8-materi-5',
    number: 5,
    title: 'Wawasan Nusantara',
    summary: 'Indonesia merupakan negara kepulauan terbesar di dunia yang membentang dari Sabang sampai Merauke, terdiri dari belasan ribu pulau serta beragam suku, agama, ras, dan budaya. Keberagaman yang luar biasa ini adalah anugerah sekaligus tantangan besar, karena tanpa kesadaran untuk bersatu, perbedaan dapat memicu keretakan. Oleh karena itu, bangsa Indonesia membutuhkan suatu konsep pandangan hidup bersama yang disebut Wawasan Nusantara untuk menjaga dan merawat keutuhan Negara Kesatuan Republik Indonesia (NKRI).',
    blocks: <MateriBlock>[
      MateriBlock(MateriBlockType.bullet, 'Wawasan Nusantara untuk Merawat Keutuhan Bangsa dan Negaraku'),
      MateriBlock(MateriBlockType.paragraph, 'Secara etimologis, istilah Wawasan Nusantara berasal dari dua kata, yaitu Wawasan dan Nusantara. Wawasan berasal dari kata "wawas" (bahasa Jawa) yang berarti pandangan, tinjauan, atau cara pandang indrawi. Nusantara berasal dari kata "nusa" (pulau/kepulauan) dan "antara" (diapit oleh dua hal: dua benua, yaitu Asia dan Australia, serta dua samudra, yaitu Pasifik dan Hindia). Secara komprehensif, Wawasan Nusantara diartikan sebagai cara pandang dan sikap bangsa Indonesia mengenai diri dan lingkungannya yang serba beragam dan bernilai strategis, dengan mengutamakan persatuan dan kesatuan bangsa serta kesatuan wilayah dalam menyelenggarakan kehidupan bermasyarakat, berbangsa, dan bernegara untuk mencapai tujuan nasional. Melalui Wawasan Nusantara, seluruh rakyat Indonesia dipersatukan dalam satu tekad: meskipun berbeda suku, bahasa daerah, dan agama, kita tetap satu bangsa yang tinggal di dalam satu wadah tanah air yang utuh.'),
      MateriBlock(MateriBlockType.paragraph, 'Lahirnya Wawasan Nusantara dipengaruhi oleh beberapa aspek penting dalam sejarah dan kondisi bangsa Indonesia: Aspek Geografis dan Wilayah: Sebelum tahun 1957, wilayah laut Indonesia masih menggunakan aturan warisan kolonial Belanda (Territoriale Zee en Maritieme Kringen Ordonnantie 1939), di mana batas laut teritorial setiap pulau hanya sejauh 3 mil dari garis pantai. Akibatnya, laut di antara pulau-pulau Indonesia dianggap sebagai laut bebas/internasional yang bisa dilalui kapal asing secara bebas. Hal ini sangat membahayakan keamanan negara. Pada tanggal 13 Desember 1957, Perdana Menteri Djuanda Kartawidjaja mencetuskan Deklarasi Djuanda, yang menyatakan bahwa laut di antara pulau-pulau Indonesia adalah wilayah teritorial Indonesia. Sejak saat itu, daratan dan lautan Indonesia menyatu menjadi satu kesatuan wilayah yang utuh.'),
      MateriBlock(MateriBlockType.paragraph, 'Aspek Falsafah Pancasila: Nilai-nilai Pancasila menjunjung tinggi persatuan, kemanusiaan, musyawarah, dan keadilan sosial. Wawasan Nusantara mengadopsi nilai-nilai ini untuk memastikan bahwa pengelolaan negara berlandaskan rasa keadilan bagi seluruh rakyat dari ujung barat hingga ujung timur. Aspek Historis (Sejarah): Bangsa Indonesia pernah mengalami masa penjajahan yang panjang akibat strategi devide et impera (adu domba). Pengalaman pahit ini menyadarkan para pendiri bangsa bahwa perpecahan hanya membawa penderitaan, sedangkan persatuan adalah kunci utama meraih dan mempertahankan kemerdekaan. Aspek Sosial Budaya: Indonesia memiliki lebih dari 1.300 suku bangsa dan ratusan bahasa daerah. Keberagaman ini diikat oleh semboyan Bhinneka Tunggal Ika, sehingga perbedaan tidak dijadikan alasan untuk berpisah, melainkan kekayaan yang saling melengkapi.'),
      MateriBlock(MateriBlockType.paragraph, 'Agar Wawasan Nusantara dapat berjalan dengan baik dan dihayati oleh seluruh warga negara, terdapat asas-asas dasar yang harus dipegang teguh:'),
      MateriBlock(MateriBlockType.bullet, 'Kepentingan yang Sama: Memiliki tujuan bersama untuk menjaga ketenteraman, keutuhan, dan kemajuan bangsa Indonesia.'),
      MateriBlock(MateriBlockType.bullet, 'Keadilan: Pembagian hasil kekayaan negara dan kesempatan pembangunan harus terbagi secara adil bagi seluruh daerah dan masyarakat.'),
      MateriBlock(MateriBlockType.bullet, 'Kejujuran: Kepatuhan terhadap aturan, keberanian berpikir, berkata, dan bertindak sesuai fakta demi kemajuan bersama.'),
      MateriBlock(MateriBlockType.bullet, 'Solidaritas: Rasa peduli, mau berkorban, dan saling membantu antarwarga negara tanpa memandang latar belakang.'),
      MateriBlock(MateriBlockType.bullet, 'Kerja Sama: Kemauan untuk bergotong royong dan berkoordinasi demi tercapainya cita-cita nasional.'),
      MateriBlock(MateriBlockType.bullet, 'Kesetiaan terhadap Kesepakatan Bersama: Setia pada ikrar bersama yang dimotori oleh Sumpah Pemuda 1928, Proklamasi Kemerdekaan 1945, dan konsensus bernegara (Pancasila, UUD 1945, NKRI, dan Bhinneka Tunggal Ika).'),
      MateriBlock(MateriBlockType.bullet, 'Pelaksanaan Wawasan Nusantara'),
      MateriBlock(MateriBlockType.paragraph, 'Wawasan Nusantara bukan sekadar konsep teori yang dihafalkan dalam pelajaran sekolah, melainkan harus diimplementasikan secara nyata dalam berbagai bidang kehidupan berbangsa dan bernegara.'),
      MateriBlock(MateriBlockType.bullet, 'Pelaksanaan dalam Bidang Politik'),
      MateriBlock(MateriBlockType.paragraph, 'Penerapan Wawasan Nusantara dalam bidang politik bertujuan untuk menciptakan penyelenggaraan negara yang sehat, dinamis, dan demokratis.'),
      MateriBlock(MateriBlockType.bullet, 'Menyelenggarakan Pemilihan Umum (Pemilu) yang jujur, adil, transparan, dan damai untuk memilih pemimpin bangsa.'),
      MateriBlock(MateriBlockType.bullet, 'Mengutamakan musyawarah mufakat dalam pengambilan keputusan publik, mulai dari tingkat RT/RW hingga tingkat nasional di DPR/MPR.'),
      MateriBlock(MateriBlockType.bullet, 'Mengembangkan sikap politik yang menjunjung tinggi Hak Asasi Manusia (HAM) serta menghormati perbedaan pendapat.'),
      MateriBlock(MateriBlockType.bullet, 'Menjaga kedaulatan NKRI dari ancaman paham separatisme atau gerakan yang ingin memisahkan diri dari negara.'),
      MateriBlock(MateriBlockType.bullet, 'Pelaksanaan dalam Bidang Ekonomi'),
      MateriBlock(MateriBlockType.paragraph, 'Dalam bidang ekonomi, Wawasan Nusantara menekankan bahwa kekayaan alam dan sumber daya di seluruh wilayah Indonesia adalah modal dan milik bersama seluruh bangsa.'),
      MateriBlock(MateriBlockType.bullet, 'Pembangunan ekonomi harus merata di seluruh wilayah Indonesia, tidak hanya terpusat di Pulau Jawa (Jawa-sentris), melainkan menjangkau daerah terdepan, terpencil, dan tertinggal (3T).'),
      MateriBlock(MateriBlockType.bullet, 'Pemanfaatan sumber daya alam (seperti tambang, hutan, dan hasil laut) dilakukan secara bijak dan berwawasan lingkungan agar dapat dinikmati oleh generasi mendatang.'),
      MateriBlock(MateriBlockType.bullet, 'Mendorong tumbuhnya Usaha Mikro, Kecil, dan Menengah (UMKM) serta partisipasi aktif masyarakat dalam roda perekonomian nasional.'),
      MateriBlock(MateriBlockType.bullet, 'Pelaksanaan dalam Bidang Sosial Budaya'),
      MateriBlock(MateriBlockType.paragraph, 'Pelaksanaan Wawasan Nusantara di bidang sosial budaya bertujuan menciptakan sikap saling menghargai dan mengakui keberagaman sebagai kekayaan nasional.'),
      MateriBlock(MateriBlockType.bullet, 'Mengembangkan dan melestarikan budaya daerah sebagai bagian utama dari kebudayaan nasional yang diakui dunia.'),
      MateriBlock(MateriBlockType.bullet, 'Menumbuhkan rasa toleransi antarumat beragama dan antaretnis dalam kehidupan sehari-hari.'),
      MateriBlock(MateriBlockType.bullet, 'Pemerataan kesempatan mendapatkan pendidikan dan layanan kesehatan yang berkualitas bagi seluruh anak bangsa tanpa terkecuali.'),
      MateriBlock(MateriBlockType.bullet, 'Menjaga nilai-nilai kearifan lokal dan tradisi gotong royong di tengah arus modernisasi.'),
      MateriBlock(MateriBlockType.bullet, 'Pelaksanaan dalam Bidang Pertahanan dan Keamanan (Hankam)'),
      MateriBlock(MateriBlockType.paragraph, 'Di bidang pertahanan dan keamanan, Wawasan Nusantara menumbuhkan kesadaran bahwa membela negara adalah hak dan kewajiban setiap warga negara Indonesia.'),
      MateriBlock(MateriBlockType.bullet, 'Penerapan Sistem Pertahanan dan Keamanan Rakyat Semesta (Sishankamrata), di mana TNI dan Polri menjadi kekuatan utama, sedangkan seluruh rakyat Indonesia berperan sebagai kekuatan pendukung.'),
      MateriBlock(MateriBlockType.bullet, 'Meningkatkan kewaspadaan terhadap ancaman yang dapat merusak persatuan, seperti penyebaran berita bohong (hoaks), ujaran kebencian, serta kejahatan siber.'),
      MateriBlock(MateriBlockType.bullet, 'Menjaga dan merawat batas-batas wilayah negara, termasuk menjaga pulau-pulau terluar agar tidak diklaim oleh negara lain.'),
      MateriBlock(MateriBlockType.paragraph, 'Sebagai seorang pelajar SMP, kamu memiliki peran yang sangat penting dalam menjaga keutuhan bangsa melalui tindakan sederhana di lingkungan sekolah dan tempat tinggalmu:'),
      MateriBlock(MateriBlockType.bullet, 'Menghormati Perbedaan di Sekolah: Tidak memilih-milih teman berdasarkan suku, agama, atau latar belakang sosial. Saat ada teman dari daerah lain, sambutlah dengan ramah dan saling belajar keunikan budaya masing-masing.'),
      MateriBlock(MateriBlockType.bullet, 'Menggunakan Bahasa Indonesia dengan Baik: Membiasakan diri berkomunikasi menggunakan bahasa Indonesia yang baik saat berinteraksi dengan teman-teman dari latar belakang yang berbeda demi memelihara persatuan.'),
      MateriBlock(MateriBlockType.bullet, 'Menjauhi Perundungan (Bullying) dan Perkelahian: Mengutamakan penyelesaian masalah secara damai dengan berdiskusi atau meminta bantuan guru dan orang tua.'),
      MateriBlock(MateriBlockType.bullet, 'Bangga terhadap Karya Bangsa Sendiri: Mencintai produk-produk dalam negeri, giat mempelajari sejarah bangsa, serta menjaga kelestarian lingkungan sekitar.'),
      MateriBlock(MateriBlockType.bullet, 'Bijak dalam Menggunakan Media Sosial: Tidak ikut menyebarkan berita yang belum jelas kebenarannya, tidak melakukan ujaran kebencian, serta selalu menyebarkan konten positif.'),
      MateriBlock(MateriBlockType.paragraph, 'Merawat keutuhan bangsa dan negara bukanlah tugas yang rumit jika kita memulainya dari rasa cinta pada tanah air. Ketika setiap warga negara, termasuk para pelajar, memandang Indonesia sebagai satu rumah besar bersama, maka tidak ada ancaman dari luar maupun dalam yang mampu memecah belah bangsa kita. Keutuhan Indonesia berada di tangan generasi muda yang mau belajar, bersatu, dan saling menghargai.'),
    ],
  ),
];
